// Bipartite check via 2-coloring (BFS)
function isBipartite(graph) {          // graph[i] = list of neighbors of node i
  const color = new Array(graph.length).fill(-1);
  for (let start = 0; start < graph.length; start++) {
    if (color[start] !== -1) continue;
    color[start] = 0;
    const queue = [start];
    while (queue.length) {
      const u = queue.shift();
      for (const v of graph[u]) {
        if (color[v] === -1) {
          color[v] = 1 - color[u];   // opposite color from parent
          queue.push(v);
        } else if (color[v] === color[u]) {
          return false;              // same-colored edge = odd cycle = not bipartite
        }
      }
    }
  }
  return true;
}

// Kuhn's algorithm: maximum bipartite matching via augmenting paths
function maxBipartiteMatching(leftSize, adj) {   // adj[l] = list of compatible right-side nodes
  const matchRight = new Array(adj.length).fill(-1);  // right node -> matched left node

  function tryAugment(l, visited) {
    for (const r of adj[l]) {
      if (visited.has(r)) continue;
      visited.add(r);
      // r is free, or r's current match can be reassigned elsewhere
      if (matchRight[r] === -1 || tryAugment(matchRight[r], visited)) {
        matchRight[r] = l;
        return true;
      }
    }
    return false;
  }

  let matches = 0;
  for (let l = 0; l < leftSize; l++) {
    if (tryAugment(l, new Set())) matches++;
  }
  return matches;
}
